-- Name: geo_district; Type: TABLE; Schema: public; Owner: -

CREATE TABLE public.geo_district (
    id integer NOT NULL,
    name_th text,
    province_th text,
    region_th text,
    cen_lon double precision,
    cen_lat double precision,
    geom public.geometry(MultiPolygon,4326)
);

CREATE SEQUENCE public.geo_district_id_seq AS integer START WITH 1 INCREMENT BY 1 NO MINVALUE NO MAXVALUE CACHE 1;

ALTER SEQUENCE public.geo_district_id_seq OWNED BY public.geo_district.id;

ALTER TABLE ONLY public.geo_district ALTER COLUMN id SET DEFAULT nextval('public.geo_district_id_seq'::regclass);


SELECT pg_catalog.setval('public.geo_district_id_seq', 879, true);

ALTER TABLE ONLY public.geo_district
    ADD CONSTRAINT geo_district_pkey PRIMARY KEY (id);

CREATE INDEX geo_district_geom_idx ON public.geo_district USING gist (geom);
